code.C:
#include <stdio.h>
#include <ctype.h>

int main() {
    char ch;
    if (scanf(" %c", &ch) == 1) {
        if (isdigit(ch)) printf("NUMBER\n");
        else if (isalpha(ch)) printf("ALPHABET\n");
        else printf("SPECIAL CHARACTER\n");
    }
    return 0;
}

