const fs = require('fs');

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        const c = s[0];
        if (/\d/.test(c)) console.log("NUMBER");
        else if (/[a-zA-Z]/.test(c)) console.log("ALPHABET");
        else console.log("SPECIAL CHARACTER");
    }
}

main();

